contracts.js:fmtMoney:
function fmtMoney(v){
  if(v === null || v === undefined || isNaN(v)) return EN;
  if(v >= 1e9) return '$' + (v/1e9).toFixed(v >= 10e9 ? 1 : 2) + 'B';
  if(v >= 1e6) return '$' + (v/1e6).toFixed(v >= 100e6 ? 0 : 1) + 'M';
  if(v >= 1e3) return '$' + Math.round(v/1e3) + 'K';
  return '$' + Math.round(v);
}

contracts.js:fmtMoneyFull:
function fmtMoneyFull(v){
  if(v === null || v === undefined || isNaN(v)) return EN;
  return '$' + Math.round(v).toLocaleString('en-US');
}

contracts.js:fmtPct:
function fmtPct(v){
  if(v === null || v === undefined || isNaN(v)) return EN;
  var p = v * 100;
  return p.toFixed(p >= 10 ? 0 : 1) + '%';
}

contracts.js:fmtDate:
function fmtDate(s){
  if(!s) return EN;
  var d = new Date(s + (s.length === 10 ? 'T00:00:00Z' : ''));
  if(isNaN(d.getTime())) return esc(s);
  var MN = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return MN[d.getUTCMonth()] + ' ' + d.getUTCDate() + ', ' + d.getUTCFullYear();
}

contracts.js:fmtMonthTick:
function fmtMonthTick(p){
  if(!p || p.length < 7) return p || '';
  var MN = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return MN[(+p.slice(5,7)) - 1] + " '" + p.slice(2,4);
}

awarded.js:fmtMonthLabel:
function fmtMonthLabel(m){
  const [y,mo] = m.split('-');
  const names = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
  return names[+mo-1] + ' ’' + y.slice(2);
}

funnel.js:fmtPeriodLong:
function fmtPeriodLong(p){
  const names=['January','February','March','April','May','June','July','August','September','October','November','December'];
  return names[+p.slice(4,6)-1] + ' ' + p.slice(0,4);
}

